172	function syncWorksDetailHead(progress: number): void {
173	  const head = document.querySelector<HTMLElement>(WORKS_DETAIL_HEAD_SELECTOR);
174	  if (!head) return;
175	  const textItems = Array.from(
176	    head.querySelectorAll<HTMLElement>(".mask-target"),
177	  );
178	  const shouldShow =
179	    progress >= WORKS_DETAIL_HEAD_TRANSITION.revealStart &&
180	    progress < WORKS_DETAIL_HEAD_TRANSITION.hideStart;
181	
182	  if (mainSceneDomState.isWorksDetailHeadVisible === shouldShow) return;
183	  mainSceneDomState.isWorksDetailHeadVisible = shouldShow;
184	  mainSceneDomState.worksDetailHeadTimers = clearTimers(
185	    mainSceneDomState.worksDetailHeadTimers,
186	  );
187	
188	  if (shouldShow) {
189	    head.dataset.active = "true";
190	    TextReveal.setVisibleOff(textItems);
191	    textItems.forEach((item, index) => {
192	      const timerId = window.setTimeout(
193	        () => {
194	          TextReveal.setVisibleOn(item);
195	        },
196	        index * WORKS_DETAIL_HEAD_TRANSITION.revealStagger * 1000,
197	      );
198	      mainSceneDomState.worksDetailHeadTimers.push(timerId);
199	    });
200	    return;
201	  }
202	
203	  textItems
204	    .slice()
205	    .reverse()
206	    .forEach((item, index) => {
207	      const timerId = window.setTimeout(
208	        () => {
209	          TextReveal.setVisibleOff(item);
210	        },
211	        index * WORKS_DETAIL_HEAD_TRANSITION.hideStagger * 1000,
212	      );
213	      mainSceneDomState.worksDetailHeadTimers.push(timerId);
214	    });
215	  const hideTimerId = window.setTimeout(
216	    () => {
217	      head.dataset.active = "false";
218	    },
219	    (Math.max(textItems.length - 1, 0) *
220	      WORKS_DETAIL_HEAD_TRANSITION.hideStagger +
221	      WORKS_DETAIL_HEAD_TRANSITION.hideSettleDuration) *
222	      1000,
223	  );
224	  mainSceneDomState.worksDetailHeadTimers.push(hideTimerId);
225	}
