241	function syncClientItems(progress: number): void {
242	  const items = Array.from(
243	    document.querySelectorAll<HTMLElement>(CLIENT_ITEM_SELECTOR),
244	  );
245	  if (items.length === 0) return;
246	
247	  const shouldShow =
248	    progress >= CLIENT_REVEAL_START && progress < CLIENT_REVEAL_END;
249	  if (mainSceneDomState.isClientItemsVisible === shouldShow) return;
250	  mainSceneDomState.isClientItemsVisible = shouldShow;
251	  mainSceneDomState.clientItemTimers = clearTimers(
252	    mainSceneDomState.clientItemTimers,
253	  );
254	
255	  const queue = shouldShow ? items : items.slice().reverse();
256	  queue.forEach((item, index) => {
257	    const timerId = window.setTimeout(
258	      () => {
259	        item.classList.add(INIT_DOM_CLASSES.blockBase);
260	        item.classList.remove(INIT_DOM_CLASSES.boxHidden);
261	        item.classList.remove("is-block-reveal-down");
262	        if (shouldShow) {
263	          BlockReveal.reveal(item);
264	          return;
265	        }
266	        item.classList.remove(INIT_DOM_CLASSES.blockUp);
267	        item.classList.add("is-block-reveal-down");
268	      },
269	      index * CLIENT_REVEAL_STAGGER_SECONDS * 1000,
270	    );
271	    mainSceneDomState.clientItemTimers.push(timerId);
272	  });
