      overflow: hidden;
    }

    .no-sub-gallery-item__img-inner {
      overflow: hidden;
    }

    // 코너 버튼 스타일
    .no-sub-gallery__corner {
      color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
    }

    /* ──────────────────────────────────────
       텍스트 콘텐츠 영역
    ────────────────────────────────────────── */
    &__content {
      margin-top: var(--gutter-md);
    }

    // ── 카테고리 섹션 ──────────────────────
    &-category {
      margin-top: var(--gutter-sm);
    }

    &-category-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    // ── 카테고리 칩 (개별 태그) ──────────────
    &-category-chip {
      padding: 0.42rem 0.8rem;
      border-radius: 999px;               // 완전히 둥근 형태
      border: 1px solid rgba(255, 255, 255, 0.16);
      background: rgba(255, 255, 255, 0.06);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
